import React, { useEffect, useState, useRef } from 'react';
import Chart from 'chart.js/auto';
import Select from 'react-select';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [selectedAircrafts, setSelectedAircrafts] = useState([]);
    const [selectedYears, setSelectedYears] = useState([]);
    const [selectedMonths, setSelectedMonths] = useState([]);
    const chartRef = useRef(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Fetched Data:', result.data);
                setData(result.data);

                // Dynamically extract unique aircrafts and years from the invoices data
                const uniqueAircrafts = [...new Set(result.data.invoices.map(item => item.Aircraft))];
                const aircraftOptions = uniqueAircrafts.map(aircraft => ({ value: aircraft, label: aircraft }));
                
                const uniqueYears = [...new Set(result.data.invoices.map(item => new Date(item['Trip start Z']).getFullYear()))];
                const yearOptions = uniqueYears.map(year => ({ value: year, label: year.toString() }));

                setAircrafts(aircraftOptions);
                setYears(yearOptions);

            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        // Access data directly
        const invoices = data.invoices;
        const loggedFlights = data.loggedFlights;

        // Filters
        let filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced' && (selectedAircrafts.length === 0 || selectedAircrafts.includes(invoice.Aircraft)));
        if (selectedYears.length > 0) {
            filteredInvoices = filteredInvoices.filter(invoice => selectedYears.includes(new Date(invoice['Trip start Z']).getFullYear()));
        }
        if (selectedMonths.length > 0) {
            filteredInvoices = filteredInvoices.filter(invoice => selectedMonths.includes(new Date(invoice['Trip start Z']).getMonth() + 1));
        }

        // Calculate revenue per hour
        const revenuePerHour = {};
        filteredInvoices.forEach(invoice => {
            const matchingFlights = loggedFlights.filter(flight => flight.Trip === invoice.Trip && flight.Aircraft === invoice.Aircraft);
            const totalFlightHours = matchingFlights.reduce((acc, cur) => acc + parseFloat(cur['Flight hrs']), 0);
            const revenue = (revenuePerHour[invoice.Aircraft] || 0) + parseFloat(invoice.Price);
            revenuePerHour[invoice.Aircraft] = revenue / (totalFlightHours || 1);
        });

        // Prepare chart data
        const labels = Object.keys(revenuePerHour);
        const chartData = labels.map(label => revenuePerHour[label]);

        // Update chart
        const ctx = chartRef.current.getContext('2d');
        if (chartRef.current) {
            chartRef.current.destroy();
        }
        chartRef.current = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [{
                    label: 'Revenue per Hour',
                    data: chartData,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }, [data, selectedAircrafts, selectedYears, selectedMonths]);

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div style={{ width: '80%', margin: 'auto' }}>
            <h1>Revenue per Hour of Aircrafts</h1>
            <Select
                isMulti
                options={aircrafts}
                onChange={(selectedOptions) => setSelectedAircrafts(selectedOptions.map(o => o.value))}
                placeholder="Select Aircrafts"
            />
            <Select
                isMulti
                options={years}
                onChange={(selectedOptions) => setSelectedYears(selectedOptions.map(o => o.value))}
                placeholder="Select Years"
            />
            <Select
                isMulti
                options={months}
                onChange={(selectedOptions) => setSelectedMonths(selectedOptions.map(o => o.value))}
                placeholder="Select Months"
            />
            <canvas ref={chartRef} style={{ width: '100%', height: '400px' }}></canvas>
        </div>
    );
};

export default ChartComponent;
